package app.relaydrop;
import android.app.*;
import android.os.Bundle;
import android.text.*;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Offline view of all retained saved-copy receipts, independent of any live pool. */
public final class LocalFilesActivity extends SecureActivity {
  private final ArrayList<JSONObject> entries=new ArrayList<>(),shown=new ArrayList<>();
  private ArrayAdapter<String> adapter;private EditText search;private TextView status;private int limit=80;private boolean opening;
  @Override public void onCreate(Bundle saved){super.onCreate(saved);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(24,32,24,24);box.setOnApplyWindowInsetsListener((v,i)->{box.setPadding(24,32+i.getSystemWindowInsetTop(),24,24+i.getSystemWindowInsetBottom());return i;});TextView title=new TextView(this);title.setText("本机文件 · 离线可用");title.setTextSize(24);box.addView(title);status=new TextView(this);status.setText("正在读取本机保存记录…");box.addView(status);search=new EditText(this);search.setSingleLine();search.setHint("搜索文件名或来源设备");box.addView(search);ListView list=new ListView(this);adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,new ArrayList<>());list.setAdapter(adapter);box.addView(list,new LinearLayout.LayoutParams(-1,0,1));Button more=new Button(this);more.setText("显示更多");more.setOnClickListener(v->{limit+=80;filter();});box.addView(more);Button back=new Button(this);back.setText("返回");back.setOnClickListener(v->finish());box.addView(back);setContentView(box);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){limit=80;filter();}public void afterTextChanged(Editable e){}});list.setOnItemClickListener((p,v,position,id)->{JSONObject receipt=shown.get(position);new AlertDialog.Builder(this).setTitle(receipt.optString("savedName",receipt.optString("name","文件"))).setMessage("文件保存在你选择的目录；不连接文件池也能打开。打开或分享前会完整校验原件哈希。\n来源："+receipt.optString("source","文件池")).setNegativeButton("取消",null).setPositiveButton("打开",(d,w)->open(receipt,false)).setNeutralButton("分享",(d,w)->open(receipt,true)).show();});new Thread(()->{try{ArrayList<JSONObject> loaded=SavedCopies.allLocal(this);runOnUiThread(()->{if(isDestroyed())return;entries.addAll(loaded);filter();});}catch(Exception e){runOnUiThread(()->status.setText("记录暂不可读，已保存原件仍在原目录。"));}},"relay-offline-files").start();}
  private void filter(){if(adapter==null)return;shown.clear();adapter.clear();String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);int matches=0;for(JSONObject r:entries){String name=r.optString("savedName",r.optString("name","文件")),source=r.optString("source","文件池");if(!(name+" "+source).toLowerCase(Locale.ROOT).contains(query))continue;matches++;if(shown.size()<limit){shown.add(r);adapter.add(name+"\n"+source+" · "+android.text.format.Formatter.formatFileSize(this,r.optLong("size")));}}status.setText("共 "+entries.size()+" 条保存记录 · 匹配 "+matches+" 条 · 显示 "+shown.size()+" 条\n已删除、移动或修改的副本会在打开时提示。");if(!SavedCopies.diagnostic().isEmpty())status.append("\n"+SavedCopies.diagnostic());adapter.notifyDataSetChanged();}
  private void open(JSONObject receipt,boolean share){if(opening||AppLock.isLocked(this))return;opening=true;Toast.makeText(this,"正在完整校验本机文件…",Toast.LENGTH_SHORT).show();new Thread(()->{try{SavedCopies.verify(this,receipt,()->{if(isFinishing()||isDestroyed()||AppLock.isLocked(this))throw new java.io.IOException("操作已取消。");});runOnUiThread(()->{opening=false;if(isDestroyed()||AppLock.isLocked(this))return;try{SavedCopies.launch(this,receipt,share);}catch(Exception e){Toast.makeText(this,"没有可用的应用，或文件授权已失效",Toast.LENGTH_LONG).show();}});}catch(Exception e){runOnUiThread(()->{opening=false;if(!isDestroyed())Toast.makeText(this,"副本已移动、删除、改变或授权失效；原文件池不受影响。",Toast.LENGTH_LONG).show();});}},"relay-offline-open").start();}
}
